-- Demo inventory (generated from lib/seed.ts — do not edit by hand).
-- Photo paths are relative (/seed/*.jpg) and served by the storefront itself.
on conflict (id) do update set
  sku = excluded.sku,
  title = excluded.title,
  description = excluded.description,
  department = excluded.department,
  category = excluded.category,
  size_label = excluded.size_label,
  size_alpha = excluded.size_alpha,
  waist_in = excluded.waist_in,
  colour = excluded.colour,
  brand = excluded.brand,
  material = excluded.material,
  condition = excluded.condition,
  price_pence = excluded.price_pence,
  suggested_price_pence = excluded.suggested_price_pence,
  rack = excluded.rack,
  photos = excluded.photos,
  tags = excluded.tags,
  status = excluded.status,
  created_at = excluded.created_at,
  receipt_id = null;
